import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import { call, profileUrl, REACTIONS, t } from '../api';
import { react, today } from '../store';
export function face(person, size = 32) {
  const style = {
    width: size + 'px',
    height: size + 'px',
    fontSize: Math.round(size * 0.42) + 'px'
  };
  if (person?.avatar) return m("img", {
    className: "QotdFace",
    src: person.avatar,
    alt: "",
    loading: "lazy",
    decoding: "async",
    style: style
  });
  const name = person?.name || '?';
  let hue = 0;
  for (const ch of name) hue = (hue * 31 + ch.charCodeAt(0)) % 360;
  return m("span", {
    className: "QotdFace QotdFace--initial",
    style: {
      ...style,
      '--qotd-face': `hsl(${hue}, 45%, 50%)`
    },
    "aria-hidden": "true"
  }, name.charAt(0).toUpperCase());
}
export function who(person) {
  if (!person) return m("span", {
    className: "QotdWho QotdWho--gone"
  }, t('answer.deleted_user'));
  return m(Link, {
    className: "QotdWho",
    href: profileUrl(person)
  }, person.name);
}

/** A row of faces: who answered (never what they said). */
export function faces(people, max = 5) {
  return m("span", {
    className: "QotdFaces"
  }, people.slice(0, max).map(person => face(person, 26)));
}
export function reactions(answer) {
  const types = Object.keys(REACTIONS);
  const shown = answer.canReact ? types : types.filter(type => (answer.reactions[type] || 0) > 0);
  if (!shown.length) return null;
  return m("div", {
    className: "QotdReactions",
    role: "group",
    "aria-label": extractText(t('answer.reactions'))
  }, shown.map(type => {
    const count = answer.reactions[type] || 0;
    const active = answer.myReaction === type;
    const label = extractText(t('reaction.' + type));
    return answer.canReact ? m("button", {
      type: "button",
      className: 'QotdReact' + (active ? ' QotdReact--active' : '') + (count ? '' : ' QotdReact--zero'),
      "aria-pressed": active ? 'true' : 'false',
      title: label,
      "aria-label": label,
      onclick: () => react(answer, type)
    }, m("span", {
      className: "QotdReact-emoji"
    }, REACTIONS[type]), count ? m("span", {
      className: "QotdReact-count"
    }, count) : null) : m("span", {
      className: "QotdReact QotdReact--static",
      title: label
    }, m("span", {
      className: "QotdReact-emoji"
    }, REACTIONS[type]), m("span", {
      className: "QotdReact-count"
    }, count));
  }));
}
/** One answer: who, when, what, and the reactions. Text only, never HTML. */
export class AnswerItem extends Component {
  editing = false;
  draft = '';
  saving = false;
  view() {
    const {
      answer,
      index = 0,
      compact
    } = this.attrs;
    return m("li", {
      className: 'QotdAnswer' + (answer.mine ? ' QotdAnswer--mine' : '') + (compact ? ' QotdAnswer--compact' : ''),
      style: {
        '--i': Math.min(index, 12)
      }
    }, face(answer.author, compact ? 28 : 36), m("div", {
      className: "QotdAnswer-main"
    }, m("div", {
      className: "QotdAnswer-meta"
    }, who(answer.author), answer.mine ? m("span", {
      className: "QotdAnswer-you"
    }, t('answer.you')) : null, m("span", {
      className: "QotdAnswer-time"
    }, humanTime(answer.createdAt)), answer.edited ? m("span", {
      className: "QotdAnswer-edited"
    }, t('answer.edited')) : null), this.editing ? this.editor() : m("p", {
      className: "QotdAnswer-body"
    }, answer.body), compact ? null : m("div", {
      className: "QotdAnswer-foot"
    }, reactions(answer), this.editing ? null : this.actions())), compact && answer.reactionsCount ? m("span", {
      className: "QotdAnswer-score"
    }, answer.reactionsCount) : null);
  }
  actions() {
    const {
      answer
    } = this.attrs;
    if (!answer.canEdit && !answer.canDelete) return null;
    return m("span", {
      className: "QotdAnswer-actions"
    }, answer.canEdit ? m("button", {
      type: "button",
      className: "QotdLinkButton",
      onclick: () => (this.editing = true, this.draft = answer.body)
    }, t('answer.edit')) : null, answer.canDelete ? m("button", {
      type: "button",
      className: "QotdLinkButton QotdLinkButton--danger",
      onclick: () => this.remove()
    }, t('answer.delete')) : null);
  }
  editor() {
    const max = this.attrs.maxLength || 280;
    return m("div", {
      className: "QotdAnswer-editor"
    }, m("textarea", {
      className: "FormControl",
      rows: 2,
      maxlength: max,
      value: this.draft,
      "aria-label": extractText(t('answer.edit')),
      oninput: e => this.draft = e.target.value
    }), m("div", {
      className: "QotdAnswer-editorButtons"
    }, m(Button, {
      className: "Button Button--primary",
      loading: this.saving,
      disabled: !this.draft.trim(),
      onclick: () => this.save()
    }, t('answer.save')), m(Button, {
      className: "Button",
      onclick: () => this.editing = false
    }, t('answer.cancel'))));
  }
  save() {
    this.saving = true;
    today.edit(this.attrs.answer.id, this.draft).then(() => this.editing = false).catch(() => {}).finally(() => (this.saving = false, m.redraw()));
  }
  remove() {
    const {
      answer
    } = this.attrs;
    if (!confirm(extractText(t(answer.mine ? 'answer.delete_mine_confirm' : 'answer.delete_confirm')))) return;
    if (this.attrs.onremove) return this.attrs.onremove(answer);
    today.remove(answer).catch(() => {});
  }
}
/** The answers, with Top / New and "More answers" (pages of 30, fetched as you go). */
export class AnswerList extends Component {
  extra = [];
  loadingMore = false;
  more = null;
  key = '';
  view() {
    const {
      answers,
      sort,
      onsort,
      count,
      reveal
    } = this.attrs;
    const key = `${this.attrs.questionId}:${sort}:${answers.map(a => a.id).join(',')}`;
    if (key !== this.key) {
      this.key = key;
      this.extra = [];
      this.more = null;
    }
    const rows = answers.concat(this.extra);
    const hasMore = this.more ?? this.attrs.hasMore;
    return m("section", {
      className: 'QotdAnswers' + (reveal ? ' QotdAnswers--reveal' : '')
    }, m("header", {
      className: "QotdAnswers-head"
    }, m("h3", {
      className: "QotdAnswers-title"
    }, t('answers.title', {
      count
    })), onsort ? m("div", {
      className: "QotdSegmented",
      role: "tablist"
    }, ['top', 'new'].map(value => m("button", {
      type: "button",
      role: "tab",
      "aria-selected": sort === value ? 'true' : 'false',
      className: sort === value ? 'active' : '',
      onclick: () => onsort(value)
    }, t('answers.sort_' + value)))) : null), rows.length ? m("ol", {
      className: "QotdAnswers-list"
    }, rows.map((answer, i) => m(AnswerItem, {
      key: answer.id,
      answer: answer,
      index: i,
      maxLength: this.attrs.maxLength
    }))) : m("p", {
      className: "QotdEmpty"
    }, t('answers.none')), hasMore ? m("div", {
      className: "QotdAnswers-more"
    }, m(Button, {
      className: "Button",
      loading: this.loadingMore,
      onclick: () => this.loadMore(rows.length)
    }, t('answers.more'))) : null);
  }
  loadMore(offset) {
    this.loadingMore = true;
    const query = new URLSearchParams({
      sort: this.attrs.sort,
      offset: String(offset)
    });
    if (today.moderating) query.set('moderate', '1');
    call('GET', `/questions/${this.attrs.questionId}/answers?${query}`).then(page => {
      const seen = new Set(this.attrs.answers.concat(this.extra).map(a => a.id));
      this.extra = this.extra.concat(page.answers.filter(a => !seen.has(a.id)));
      this.more = page.hasMore;
    }).catch(() => {}).finally(() => (this.loadingMore = false, m.redraw()));
  }
}

/** Opens the log-in modal (a lazy chunk in Flarum 2). */
export function logIn() {
  app.modal.show(() => globalThis.flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
}
