import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { t } from '../api';
import { today } from '../store';
import QuestionCard from './QuestionCard';
import { AnswerItem, face, who } from './parts';

/**
 * The front-page card: today's question to answer, and once you have, the
 * three best answers so far. Under it, yesterday's top answer.
 */
export default class Hero extends Component {
  hidden = false;
  oninit(vnode) {
    super.oninit(vnode);
    today.load();
  }
  view() {
    const data = today.data;
    if (this.hidden || today.failed || !data && !today.loading) return m("div", {
      className: "QotdHero QotdHero--empty"
    });
    if (!data) return m("div", {
      className: "QotdHero QotdHero--placeholder",
      "aria-hidden": "true"
    });
    const question = data.question;
    if (!question) return m("div", {
      className: "QotdHero QotdHero--empty"
    });
    return m("div", {
      className: "QotdHero"
    }, m(QuestionCard, {
      data: data,
      question: question,
      variant: "hero",
      ondismiss: () => this.dismiss()
    }), question.mine && question.answers?.length ? this.peek(question) : null, data.previous?.top ? topAnswer(data.previous, data.previous.top) : null);
  }
  peek(question) {
    const others = question.answers.filter(a => !a.mine).slice(0, 3);
    if (!others.length) return null;
    return m("ol", {
      className: "QotdHero-peek QotdAnswers--reveal"
    }, others.map((answer, i) => m(AnswerItem, {
      key: answer.id,
      answer: answer,
      index: i,
      compact: true
    })));
  }

  /** Hidden until the forum's next question (stored as that moment). */
  dismiss() {
    this.hidden = true;
    try {
      localStorage.setItem('qotd-hidden-until', String(new Date(today.data.nextAt).getTime()));
    } catch (e) {}
  }
}

/** "🏆 Yesterday's top answer", with yesterday's question for context. */
export function topAnswer(question, answer, label = 'top.yesterday') {
  return m("aside", {
    className: "QotdTop"
  }, m("span", {
    className: "QotdTop-trophy",
    "aria-hidden": "true"
  }, "\uD83C\uDFC6"), m("div", {
    className: "QotdTop-main"
  }, m("div", {
    className: "QotdTop-label"
  }, t(label), m(Link, {
    className: "QotdTop-question",
    href: app.route('question-of-the-day.question', {
      id: question.id
    })
  }, question.body)), m("blockquote", {
    className: "QotdTop-answer"
  }, answer.body), m("div", {
    className: "QotdTop-by"
  }, face(answer.author, 22), who(answer.author), m("span", {
    className: "QotdTop-count"
  }, m(Icon, {
    name: "fas fa-heart"
  }), " ", t('top.reactions', {
    count: answer.reactionsCount
  })))));
}
flarum.reg.add('ernestdefoe-question-of-the-day', 'forum/components/Hero', Hero);