import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import { dayLabel, t, until } from '../api';
import { today } from '../store';
import { face, faces, who, logIn } from './parts';
const DRAFT = 'qotd-draft';

/**
 * The question, big: the date, who suggested it, and then one of
 *  - a box to answer it, with "N members answered" and their faces (answers locked),
 *  - your answer (once posted), or
 *  - for a past question, how many answered.
 */
export default class QuestionCard extends Component {
  draft = '';
  posting = false;
  timer = 0;
  oninit(vnode) {
    super.oninit(vnode);
    try {
      const saved = JSON.parse(sessionStorage.getItem(DRAFT) || 'null');
      if (saved && saved.id === this.attrs.question.id) this.draft = saved.text || '';
    } catch (e) {}
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    // The "next question in…" countdown, once a minute.
    this.timer = window.setInterval(() => m.redraw(), 60e3);
  }
  onremove(vnode) {
    super.onremove(vnode);
    clearInterval(this.timer);
  }
  view() {
    const {
      question,
      variant,
      data
    } = this.attrs;
    const past = variant === 'past' || !question.open;
    return m("article", {
      className: `QotdCard QotdCard--${variant}` + (past ? ' QotdCard--closed' : ''),
      "aria-labelledby": `qotd-q-${question.id}`
    }, m("div", {
      className: "QotdCard-glow",
      "aria-hidden": "true"
    }), m("header", {
      className: "QotdCard-top"
    }, m("span", {
      className: "QotdCard-badge"
    }, m(Icon, {
      name: "fas fa-comment-dots"
    }), t('card.badge')), m("span", {
      className: "QotdCard-date"
    }, dayLabel(question.askedOn, past)), m("span", {
      className: "QotdCard-tools"
    }, this.tools())), m("h2", {
      className: "QotdCard-question",
      id: `qotd-q-${question.id}`
    }, variant === 'hero' ? m(Link, {
      href: app.route('question-of-the-day'),
      className: "QotdCard-questionLink"
    }, question.body) : question.body), question.suggestedBy ? m("p", {
      className: "QotdCard-by"
    }, face(question.suggestedBy, 20), t('card.suggested_by', {
      name: who(question.suggestedBy)
    })) : null, past ? this.pastFoot() : question.mine ? this.answered() : this.form());
  }
  tools() {
    const {
      data,
      variant,
      question
    } = this.attrs;
    const items = [];
    if (data.streak.current > 0 && question.open) {
      items.push(m("span", {
        className: "QotdChip QotdChip--streak",
        title: extractText(t('streak.title', {
          count: data.streak.current
        }))
      }, "\uD83D\uDD25 ", data.streak.current));
    }
    if (question.open && variant !== 'past') {
      items.push(m("span", {
        className: "QotdChip QotdChip--next",
        title: extractText(t('card.next_title'))
      }, m(Icon, {
        name: "far fa-clock"
      }), " ", until(data.nextAt)));
    }
    if (variant === 'hero' && this.attrs.ondismiss) {
      items.push(m("button", {
        type: "button",
        className: "QotdCard-dismiss",
        title: extractText(t('card.hide')),
        "aria-label": extractText(t('card.hide')),
        onclick: () => this.attrs.ondismiss()
      }, m(Icon, {
        name: "fas fa-times"
      })));
    }
    return items;
  }
  form() {
    const {
      data,
      question
    } = this.attrs;
    const count = question.answersCount || 0;
    const max = data.maxLength;
    const left = max - this.draft.length;
    if (!app.session.user) {
      return m("div", {
        className: "QotdCard-guest"
      }, this.lock(count), m(Button, {
        className: "Button Button--primary QotdCard-cta",
        onclick: () => logIn()
      }, t('card.log_in')));
    }
    if (!data.can.answer) {
      return m("div", {
        className: "QotdCard-guest"
      }, this.lock(count), m("p", {
        className: "QotdCard-note"
      }, t('card.no_permission')));
    }
    return m("form", {
      className: "QotdCard-form",
      onsubmit: e => this.submit(e)
    }, m("label", {
      className: "sr-only",
      for: `qotd-a-${question.id}`
    }, t('card.your_answer')), m("textarea", {
      id: `qotd-a-${question.id}`,
      className: "FormControl QotdCard-input",
      rows: 2,
      maxlength: max,
      placeholder: extractText(t('card.placeholder')),
      value: this.draft,
      oninput: e => {
        this.draft = e.target.value;
        this.keepDraft();
      },
      onkeydown: e => {
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) this.submit(e);
      }
    }), m("div", {
      className: "QotdCard-formRow"
    }, this.lock(count), m("span", {
      className: 'QotdCard-left' + (left < 20 ? ' QotdCard-left--low' : ''),
      "aria-live": "polite"
    }, left < 60 ? left : ''), m(Button, {
      type: "submit",
      className: "Button Button--primary QotdCard-cta",
      loading: this.posting,
      disabled: !this.draft.trim()
    }, t('card.post'))));
  }

  /** "🔒 12 answers, hidden until you post yours", with the answerers' faces. */
  lock(count) {
    const {
      question
    } = this.attrs;
    return m("span", {
      className: "QotdCard-lock"
    }, question.answerers?.length ? faces(question.answerers) : null, m("span", {
      className: "QotdCard-lockText"
    }, m(Icon, {
      name: "fas fa-lock"
    }), " ", count ? t('card.locked', {
      count
    }) : t('card.be_first')));
  }
  answered() {
    const {
      question,
      variant
    } = this.attrs;
    const others = Math.max(0, (question.answersCount || 1) - 1);
    return m("div", {
      className: "QotdCard-answered"
    }, m("div", {
      className: "QotdCard-mine"
    }, m("span", {
      className: "QotdCard-check",
      "aria-hidden": "true"
    }, m(Icon, {
      name: "fas fa-check"
    })), m("div", null, m("span", {
      className: "QotdCard-mineLabel"
    }, t('card.your_answer')), m("p", {
      className: "QotdCard-mineText"
    }, question.mine.body))), variant === 'hero' ? m("div", {
      className: "QotdCard-formRow"
    }, m("span", {
      className: "QotdCard-lock"
    }, question.answerers?.length ? faces(question.answerers) : null, m("span", {
      className: "QotdCard-lockText"
    }, others ? t('card.others', {
      count: others
    }) : t('card.first'))), m(Link, {
      className: "Button Button--primary QotdCard-cta",
      href: app.route('question-of-the-day')
    }, t('card.see_answers'), " ", m(Icon, {
      name: "fas fa-arrow-right"
    }))) : null);
  }
  pastFoot() {
    const {
      question
    } = this.attrs;
    return m("p", {
      className: "QotdCard-note"
    }, m(Icon, {
      name: "fas fa-comments"
    }), " ", t('card.closed', {
      count: question.answersCount || 0
    }), question.discussion ? m('[', null, ' · ', m(Link, {
      href: app.route('discussion', {
        id: `${question.discussion.id}-${question.discussion.slug}`
      })
    }, t('card.discussion'))) : null);
  }
  keepDraft() {
    try {
      sessionStorage.setItem(DRAFT, JSON.stringify({
        id: this.attrs.question.id,
        text: this.draft
      }));
    } catch (e) {}
  }
  submit(e) {
    e.preventDefault();
    if (this.posting || !this.draft.trim()) return;
    this.posting = true;
    today.answer(this.draft).then(() => {
      this.draft = '';
      try {
        sessionStorage.removeItem(DRAFT);
      } catch (err) {}
      this.attrs.onanswered?.();
    }).catch(() => {
      // Closed while they typed (midnight): bring in the new question, keep their words.
      today.load(true);
    }).finally(() => {
      this.posting = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-question-of-the-day', 'forum/components/QuestionCard', QuestionCard);